import { forwardRef } from "react";
import text from "@generated/text.module.css";
import color from "@generated/color.module.css";
import styles from "./Text.module.css";
import { cx, useKitRoot } from "./util.js";

const DEFAULT_TAGS = { display_1: "h1", display_2: "h1", headline_1: "h2", headline_2: "h2", headline_3: "h3" };

export const Text = forwardRef(function Text({ as, variant = "body_2", color: colorName, align, ellipsis, clamp, strike, nowrap, mixin, className, children, ...rest }, ref) {
    const Element = as ?? "div";
    const root = useKitRoot([styles.text, text[variant], colorName && color[`fg_${colorName}`], align && text[`align_${align}`], ellipsis && text.ellipsis, clamp && text[`clamp_${clamp}`], strike && text.strike, nowrap && text.nowrap], mixin, className, undefined, ref);
    return <Element {...root} {...rest}>{children}</Element>;
});

export function Title({ variant = "headline_3", as, subtitle, className, children, ...rest }) {
    return (
        <div className={cx(styles.title, className)}>
            <Text as={as ?? DEFAULT_TAGS[variant] ?? "h3"} variant={variant} className={styles.heading} {...rest}>{children}</Text>
            {subtitle ? <Text variant="body_2" color="alt" className={styles.subtitle}>{subtitle}</Text> : null}
        </div>
    );
}

export const Link = forwardRef(function Link({ href = "#", variant, onClick, className, children, external, mixin, ...rest }, ref) {
    const root = useKitRoot([styles.link, variant && text[variant]], mixin, className, undefined, ref);
    return (
        <a href={href} {...root} onClick={onClick} target={external ? "_blank" : undefined} rel={external ? "noopener" : undefined} {...rest}>
            {children}
        </a>
    );
});

export function VisuallyHidden({ as: Element = "span", children }) {
    return <Element className={text.visually_hidden}>{children}</Element>;
}

export function BulletList({ items, className }) {
    return (
        <ul className={cx(styles.bullets, className)}>
            {items.map((item, i) => <li key={i} className={styles.bullet}>{item}</li>)}
        </ul>
    );
}
