import { forwardRef } from "react";
import layout from "@generated/layout.module.css";
import color from "@generated/color.module.css";
import styles from "./Box.module.css";
import { cx, responsiveClasses, useKitRoot } from "./util.js";

export const Box = forwardRef(function Box({ as: Element = "div", padding, background, border, radius, elevation, mixin, className, style, children, ...rest }, ref) {
    const root = useKitRoot([styles.box, responsiveClasses("p", padding), background && color[`bg_${background}`], border && color[border === true ? "border" : `border_${border}`], radius && color[`radius_${radius}`], elevation && color[`elevation_${elevation}`]], mixin, className, style, ref);
    return <Element {...root} {...rest}>{children}</Element>;
});

export const Stack = forwardRef(function Stack({ as: Element = "div", direction = "column", gap = 2, alignItems, justifyContent, wrap, grow, mixin, className, style, children, ...rest }, ref) {
    const root = useKitRoot([styles.stack, layout.flex, layout[`direction_${direction}`], responsiveClasses("gap", gap), alignItems && layout[`align_${alignItems}`], justifyContent && layout[`justify_${justifyContent}`], wrap && layout.wrap, grow && layout.grow], mixin, className, style, ref);
    return <Element {...root} {...rest}>{children}</Element>;
});

export function StackItem({ grow, shrink = true, className, children, ...rest }) {
    return <div className={cx(styles.item, grow && layout.grow, !shrink && layout.shrink_0, className)} {...rest}>{children}</div>;
}

export function Inline(props) {
    return <Stack direction="row" alignItems="center" {...props} />;
}

export function Grid({ columns = 12, gap = 4, className, children, ...rest }) {
    const columnClass = typeof columns === "object" ? cx(layout[`columns_${columns.base}`], columns.medium && layout[`columns_${columns.medium}--medium`], columns.large && layout[`columns_${columns.large}--large`]) : layout[`columns_${columns}`];
    return <div className={cx(styles.grid, layout.grid, columnClass, responsiveClasses("gap", gap), className)} {...rest}>{children}</div>;
}

export function GridColumn({ size = 1, className, children }) {
    return <div className={cx(styles.column, className)} style={{ "--tk_grid-span": size }}>{children}</div>;
}

export function Divider({ vertical, mixin, className }) {
    const root = useKitRoot([styles.divider, vertical && styles.vertical], mixin, className);
    return <hr aria-hidden="true" {...root} />;
}

export function Spacer({ size = 4 }) {
    return <div aria-hidden="true" className={responsiveClasses("mb", size)} />;
}
