import { useId } from "react";
import styles from "./Stepper.module.css";
import { IconButton } from "./Button.jsx";
import { cx } from "./util.js";

export function Stepper({ label, value, min = 0, max = 10, onChange, a11yLabel, className, testId }) {
    const id = useId();
    return (
        <div className={cx(styles.stepper, className)} data-testid={testId}>
            <label id={id} className={styles.label}>{label}</label>
            <div className={styles.controls} role="group" aria-labelledby={id}>
                <IconButton icon="minus" label={`${a11yLabel}: decrease`} variant="secondary" size="medium" disabled={value <= min} onClick={() => onChange?.(value - 1)} />
                <span className={styles.value} aria-live="polite">{value}</span>
                <IconButton icon="plus" label={`${a11yLabel}: increase`} variant="secondary" size="medium" disabled={value >= max} onClick={() => onChange?.(value + 1)} />
            </div>
        </div>
    );
}
