import { forwardRef, useMemo } from "react";
import styles from "./Button.module.css";
import { Icon } from "./Icon.jsx";
import { Spinner } from "./Spinner.jsx";
import { cx, useKitRoot } from "./util.js";

function ButtonIcon({ name, size }) {
    const iconSize = useMemo(() => (size === "large" ? "medium" : "small"), [size]);
    return <Icon name={name} size={iconSize} className={styles.icon} />;
}

function ButtonText({ children, truncate = true }) {
    const className = useMemo(() => cx(styles.text, !truncate && styles.wrap), [truncate]);
    return <span className={className}>{children}</span>;
}

export const Button = forwardRef(function Button({ variant = "primary", size = "medium", wide, icon, iconPosition = "start", loading, href, type = "button", mixin, className, children, ...rest }, ref) {
    const content = (
        <>
            {loading ? <Spinner size="small" className={styles.spinner} /> : null}
            {icon && iconPosition === "start" ? <ButtonIcon name={icon} size={size} /> : null}
            {children ? <ButtonText>{children}</ButtonText> : null}
            {icon && iconPosition === "end" ? <ButtonIcon name={icon} size={size} /> : null}
        </>
    );
    const root = useKitRoot([styles.button, styles[variant], styles[size], wide && styles.wide, loading && styles.loading, !children && styles.iconOnly], mixin, className, undefined, ref);
    if (href)
        return <a href={href} {...root} {...rest}>{content}</a>;
    return <button type={type} {...root} {...rest}>{content}</button>;
});

export const IconButton = forwardRef(function IconButton({ icon, label, variant = "tertiary-neutral", size = "medium", className, ...rest }, ref) {
    return <Button ref={ref} variant={variant} size={size} icon={icon} aria-label={label} className={cx(styles.iconButton, className)} {...rest} />;
});

export function ButtonGroup({ children, className }) {
    return <div role="group" className={cx(styles.group, className)}>{children}</div>;
}
