import { PureComponent } from "react";
import styles from "./Icon.module.css";
import { cx } from "./util.js";
import { iconPath } from "./icons.js";

const SIZES = { smaller: 12, small: 16, medium: 20, large: 24, larger: 32 };

// The legacy kit's icon, a class component.
export class Icon extends PureComponent {
    render() {
        const { name, size = "medium", color, label, className } = this.props;
        const pixels = SIZES[size] ?? 20;
        return (
            <span className={cx(styles.icon, styles[size], color && styles[color], className)} role={label ? "img" : undefined} aria-label={label} aria-hidden={label ? undefined : "true"}>
                <svg viewBox="0 0 24 24" width={pixels} height={pixels} focusable="false">
                    <path d={iconPath(name)} />
                </svg>
            </span>
        );
    }
}
