import { PureComponent } from "react";
import styles from "./Image.module.css";
import { cx } from "./util.js";

// The lazy image of the legacy kit, a class component: a native
// lazy-loading <img> over a placeholder colour. It doesn't re-render when the
// image loads, so that image timing never adds work to a step.
export class Image extends PureComponent {
    render() {
        const { src, srcSet, sizes, alt, width, height, ratio, placeholderColor, fit = "cover", eager, className } = this.props;
        return (
            <div className={cx(styles.frame, className)} style={{ "--tk_image-ratio": ratio ?? (width && height ? `${width} / ${height}` : undefined), "--tk_image-placeholder": placeholderColor }}>
                <img className={cx(styles.image, styles[fit])} src={src} srcSet={srcSet} sizes={sizes} alt={alt} width={width} height={height} loading={eager ? "eager" : "lazy"} decoding="async" />
            </div>
        );
    }
}
